[
  {
    "statement": "No information regarding the cost-effectiveness of amphibian habitat restoration methods was found in the provided action documents.",
    "citations": [
      "840",
      "853",
      "879"
    ]
  },
  {
    "statement": "One study in Italy indicated that restoring connectivity between two wetlands by raising a road on a viaduct led to a significant decrease in the deaths of migrating amphibians.",
    "citations": [
      "840"
    ]
  },
  {
    "statement": "A study in Australia found that retaining native vegetation corridors successfully maintained populations of eight out of 13 frog species over a 20-year period.",
    "citations": [
      "853"
    ]
  },
  {
    "statement": "A global review of wetland restoration showed that in 89% of cases, restored and created wetlands had amphibian abundance or species numbers similar to or higher than natural wetlands.",
    "citations": [
      "879"
    ]
  },
  {
    "statement": "Seven of nine studies in Canada, Taiwan, and the USA reported that wetland restoration increased the number of amphibian species.",
    "citations": [
      "879"
    ]
  },
  {
    "statement": "Breeding populations of amphibians established in some instances of wetland restoration.",
    "citations": [
      "879"
    ]
  }
]

[
  {
    "statement": "There is no evidence for the effects of planting, maintaining or restoring hedges on amphibian populations.",
    "citations": [
      "791",
      "790"
    ]
  },
  {
    "statement": "One study on connectivity for reptiles found that in an area with hedges connecting different habitat types there were more unique reptile species.",
    "citations": [
      "3663"
    ]
  },
  {
    "statement": "One study on connectivity for reptiles found that reptile communities were more similar across different habitat types in an area with hedges connecting them than in an area with no hedges.",
    "citations": [
      "3663"
    ]
  },
  {
    "statement": "Another study found that forest fragments connected by corridors and isolated forest fragments had similar reptile species richness.",
    "citations": [
      "3663"
    ]
  },
  {
    "statement": "Another study found that forest fragments connected by corridors and isolated forest fragments had similar reptile species composition.",
    "citations": [
      "3663"
    ]
  },
  {
    "statement": "Another study found that forest fragments connected by corridors and isolated forest fragments had a similar abundance of reptiles.",
    "citations": [
      "3663"
    ]
  }
]

[
  {
    "statement": "There is no evidence for the effects of reduced tillage on amphibian populations.",
    "citations": [
      "789"
    ]
  },
  {
    "statement": "Studies have looked at the impact of reduced tillage on other wildlife.",
    "citations": []
  },
  {
    "statement": "In Europe, some studies found positive effects of reduced tillage on earthworms, some invertebrates, weeds, or farmland birds.",
    "citations": [
      "126"
    ]
  },
  {
    "statement": "The positive effects of reduced tillage included increased biomass, species richness, or abundance.",
    "citations": [
      "126"
    ]
  },
  {
    "statement": "One review noted that tillage had negative effects on invertebrate numbers.",
    "citations": [
      "126"
    ]
  },
  {
    "statement": "No-till systems had more invertebrate bird food resources.",
    "citations": [
      "126"
    ]
  },
  {
    "statement": "Studies in Europe reported that reducing tillage had negative, no, or inconsistent effects on the abundance, biomass, or species richness of some invertebrates, earthworms, plants, mammals, and birds.",
    "citations": [
      "126"
    ]
  },
  {
    "statement": "In North America, Canada, and the UK, some studies found that some or all bird groups had higher species richness or diversity on reduced-tillage fields.",
    "citations": [
      "211"
    ]
  },
  {
    "statement": "Other studies in North America, Canada, and the UK found lower or no difference in bird diversity for some measures on reduced-tillage fields.",
    "citations": [
      "211"
    ]
  },
  {
    "statement": "Some bird species were found at higher densities on reduced-tillage fields.",
    "citations": [
      "211"
    ]
  },
  {
    "statement": "Other bird species were found at similar or lower densities on reduced-tillage fields.",
    "citations": [
      "211"
    ]
  }
]

[
  {
    "statement": "There is no evidence for the effects of commercially breeding amphibians for the pet trade on wild amphibian populations.",
    "citations": [
      "794"
    ]
  },
  {
    "statement": "In a review, reducing trade in two frog species through legislation allowed populations to recover from over-exploitation.",
    "citations": [
      "824"
    ]
  },
  {
    "statement": "No evidence was found for the effects of using amphibians sustainably.",
    "citations": [
      "793"
    ]
  }
]

[
  {
    "statement": "Several studies have investigated the effectiveness of creating new ponds for great crested newts.",
    "citations": []
  },
  {
    "statement": "No studies have explicitly mentioned the cost-effectiveness of methods for creating new ponds for great crested newts.",
    "citations": []
  },
  {
    "statement": "In Germany and the UK, studies found that great crested newts established breeding populations in 57–75% of created ponds or sites.",
    "citations": [
      "863"
    ]
  },
  {
    "statement": "The great crested newts that established breeding populations were either naturally colonizing, captive-bred, or translocated.",
    "citations": [
      "863"
    ]
  },
  {
    "statement": "Studies in the UK showed that up to 88% of created ponds were colonized by translocated or small numbers of naturally colonizing great crested newts.",
    "citations": [
      "863"
    ]
  },
  {
    "statement": "A study in the UK found that head-started great crested newts reproduced in 38% of created ponds.",
    "citations": [
      "863"
    ]
  },
  {
    "statement": "A systematic review in the UK found no conclusive evidence that mitigation efforts for great crested newts lead to self-sustaining populations.",
    "citations": [
      "863"
    ]
  },
  {
    "statement": "Mitigation efforts for great crested newts often include pond creation.",
    "citations": [
      "863"
    ]
  },
  {
    "statement": "Studies in France, Germany, and the USA found that naturally colonizing alpine newts, captive-bred smooth newts, or translocated spotted salamanders established stable breeding populations in 20–100% of created ponds.",
    "citations": [
      "867"
    ]
  },
  {
    "statement": "Studies in France and China found that alpine newts or Chinhai salamanders reproduced in 60–100% of created ponds.",
    "citations": [
      "867"
    ]
  },
  {
    "statement": "A study in the USA found that translocated spotted salamanders reproduced in created ponds, but tiger salamanders did not.",
    "citations": [
      "867"
    ]
  },
  {
    "statement": "A study in the USA found that draining ponds to eliminate fish increased the number of amphibian species.",
    "citations": [
      "826"
    ]
  },
  {
    "statement": "A study in Estonia showed that pond restoration and pond creation led to an increase in the numbers of species and breeding populations of common spadefoot toads and great crested newts when compared to no management.",
    "citations": [
      "826"
    ]
  },
  {
    "statement": "The pond restoration in the Estonian study sometimes included drying to eliminate fish.",
    "citations": [
      "826"
    ]
  },
  {
    "statement": "Studies in the UK and USA found that drying ponds to eliminate fish increased the breeding success of frog or newt species.",
    "citations": [
      "826"
    ]
  },
  {
    "statement": "The drying of ponds to eliminate fish was sometimes done in conjunction with other management activities.",
    "citations": [
      "826"
    ]
  }
]

[
  {
    "statement": "There is no evidence for the effects of planting hedges on amphibian populations.",
    "citations": [
      "791"
    ]
  }
]

[
  {
    "statement": "Two studies in Germany found that closing roads during seasonal amphibian migration protected large numbers of amphibians from death.",
    "citations": [
      "842"
    ]
  },
  {
    "statement": "Seven of eight studies in Germany, Canada and the USA found that barrier fencing with culverts decreased amphibian road deaths.",
    "citations": [
      "756"
    ]
  }
]

[
  {
    "statement": "No evidence was found in the documents to answer the query about which amphibian species are most genetically vulnerable to future climate change.",
    "citations": []
  }
]
